for _ntl_phrase, _sp_phrase in _NOUN_PHRASES_NTL_SP.items():
	_existing = NOUNS_NTL_SP.get(_ntl_phrase)
	if _existing is None:
		NOUNS_NTL_SP[_ntl_phrase] = _sp_phrase
	else:
		_existing_values = _existing if isinstance(_existing, list) else [_existing]
		_new_values = _sp_phrase if isinstance(_sp_phrase, list) else [_sp_phrase]
		_merged = list(_existing_values)
		for _value in _new_values:
			if _value not in _merged:
				_merged.append(_value)
		NOUNS_NTL_SP[_ntl_phrase] = _merged if len(_merged) > 1 else _merged[0]
